package pe.edu.upeu.casaonada.pago.service;
import pe.edu.upeu.casaonada.pago.domain.*; import pe.edu.upeu.casaonada.pago.dto.*; import pe.edu.upeu.casaonada.pago.exception.ResourceNotFoundException; import pe.edu.upeu.casaonada.pago.integration.MercadoPagoGateway; import pe.edu.upeu.casaonada.pago.repository.PagoRepository; import org.springframework.beans.factory.ObjectProvider; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class PagoService { private final PagoRepository repo; private final ObjectProvider<MercadoPagoGateway> mp; public PagoService(PagoRepository r,ObjectProvider<MercadoPagoGateway> mp){repo=r;this.mp=mp;}
 @Transactional public PagoResponse crear(PagoRequest r,String key){ String idem=(key==null||key.isBlank())?UUID.randomUUID().toString():key; var existing=repo.findByIdempotencyKey(idem); if(existing.isPresent()) return map(existing.get()); Pago p=new Pago();p.setOrdenId(r.ordenId());p.setMonto(r.monto());p.setMoneda(r.moneda().toUpperCase());p.setProveedor("MERCADO_PAGO");p.setIdempotencyKey(idem);p.setEstado(EstadoPago.CREADO); var gateway=mp.getIfAvailable(); if(gateway!=null){var rr=gateway.pagar(r,idem);p.setProviderPaymentId(rr.providerPaymentId());p.setEstado(rr.estado());} else p.setEstado(EstadoPago.PENDIENTE); return map(repo.save(p)); }
 @Transactional(readOnly=true) public List<PagoResponse> listar(){return repo.findAll().stream().map(this::map).toList();} @Transactional(readOnly=true) public PagoResponse buscar(Long id){return map(repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Pago no encontrado: "+id)));}
 private PagoResponse map(Pago p){return new PagoResponse(p.getId(),p.getOrdenId(),p.getMonto(),p.getMoneda(),p.getProveedor(),p.getProviderPaymentId(),p.getIdempotencyKey(),p.getEstado(),p.getCreatedAt(),p.getUpdatedAt());} }
